var o=[{title:`Objetivos de resultado y de proceso`,text:`Un objetivo de resultado nombra lo que quieres lograr, por ejemplo ocho flexiones controladas o caminar 30 minutos sin parar. Un objetivo de proceso nombra la conducta que te lleva ahí, como dos sesiones de fuerza cada semana. Los resultados te motivan, y los procesos te dan el plan diario.`},{title:`Objetivos SMART`,text:`Un objetivo práctico es específico, medible, alcanzable, relevante y con plazo. «Ponerme en forma» es demasiado vago. Prueba con «hacer dos entrenamientos de cuerpo completo de 30 minutos a la semana durante seis semanas y pasar de 10 a 20 minutos mi caminata continua cómoda». Tu meta exacta debe depender de tu capacidad actual, tu salud y tu horario.`},{title:`Fija un punto de partida`,text:`Antes de empezar, anota algo que puedas repetir: la variante de flexión que haces con buena forma, la carga y las repeticiones en un movimiento conocido o cuánto tiempo puedes caminar cómodamente. Compara cosas equivalentes. Muchos principiantes mejoran notablemente en las primeras semanas, pero los cambios de fuerza y de composición corporal varían mucho, así que nadie puede prometer con fiabilidad un ritmo concreto de ganancia muscular o pérdida de grasa.`},{title:`Prevé las interrupciones`,text:`Decide una versión mínima del objetivo para las semanas ocupadas, como un entrenamiento más corto en lugar de una sesión omitida. No fijes varias metas agresivas a la vez. Si un objetivo es tan difícil que exige una velocidad poco segura o demasiado volumen de entrenamiento, redúcelo.`},{title:`Revisa y ajusta`,text:`Vuelve a evaluar cada cuatro a ocho semanas. Si cumples el plan pero el progreso es lento, cambia una variable de entrenamiento o date más tiempo. Si sigues faltando a las sesiones, arregla el horario antes de añadir ejercicios.`},{title:`Cómo usar TrainUp`,text:`Tu objetivo, tus días de entrenamiento y la duración de la sesión están en Perfil. Durante cada entrenamiento marcas las series y anotas tus repeticiones, y después valoras tu esfuerzo. El Historial te muestra si tu objetivo de proceso se cumple semana a semana.`}];var t=[{label:`CDC: empezar y mantener la actividad`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`},{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:o,sources:t};export{s as default,o as sections,t as sources};